def blockCompositeCoefficient (b c : NormalizedBlockSystem 𝕜) (n k : ℕ) : 𝕜 :=
  ∑ j ∈ c.support n, c.coefficient n j *
    (if k ∈ b.support j then b.coefficient j k else 0)

